## dstn
psf_always_emit         = 0x0000000002  # Forces emit, unrelated to other factors such as distance. Necessary when particles are a gameplay mechanic ala NW.
psf_global_emit_dir     = 0x0000000010  # Inherits a GLOBAL emission vector. All Particles using this follow the same emission path. Probably used in rain
psf_emit_at_water_level = 0x0000000020  # Used for water splashies, emits the particle at the water level to look like trudging through water.
psf_billboard_2d        = 0x0000000100  # Cylindrical Billboarding, Points the front vector to the camera, will rotate on just the z axis to accomplish this
psf_billboard_3d        = 0x0000000200  # Spherical Billboarding, Points to front vector to the camera, will rotate on both x,z axis to accomplish this
psf_billboard_drop      = 0x0000000300  # Never saw this before
psf_turn_to_velocity    = 0x0000000400  # Points the particle's front vector towards the velocity vector.
psf_randomize_rotation  = 0x0000001000  # Randomizes the initial particle rotation
psf_randomize_size      = 0x0000002000  # Randomizes the initial particle size
psf_2d_turbulance       = 0x0000010000  # Never thought of this one before
psf_next_effect_is_lod  = 0x0000020000  # NEW: Meant to be used for more performance friendly effects to be rendered at a distance. For always emit particles.